                                                                                                                                                                                                     
  CREATE TABLE "TENANT_ANALYZE_TEMPLATE_ITEM"                                                                                                                                             
   (	"ITEM_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"ITEM_NAME" NVARCHAR2(255) NOT NULL ENABLE,                                                                                                                                                         
	"ITEM_TYPE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                          
	"ANALYZE_TEMPLATE_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                       
	"CREATED_BY" NUMBER,                                                                                                                                                                                
	"CREATED_DATE" DATE DEFAULT sysdate,                                                                                                                                                                
	"UPDATED_BY" NUMBER,                                                                                                                                                                                
	"UPDATED_DATE" DATE DEFAULT sysdate,                                                                                                                                                                
	"REMARK" NVARCHAR2(255),                                                                                                                                                                            
	"TENANT_ID" NUMBER DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                       
	"SORT_NUM" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	 PRIMARY KEY ("ITEM_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

